BallPossession
en:
gameState.possession = 0;
en,du:
% Calculate distances from robots to ball
% (Goalkeepers get 2x the range)
for idx = 1:numRobots
    ballDists(idx) = norm( sensors(idx).pose(1:2) - ballPose' );
    if behavior(idx).role == Role.Goalkeeper
        ballDists(idx) = ballDists(idx)/2;
    end
end
% Find the robot index of the current and latest possessions
robotIdx = findPossession;
if robotIdx > 0
    lastPossession = robotIdx;
end
% Unpack the robot commands
action = commands(lastPossession).action;
ballVel = commands(lastPossession).ballVelocity;
robotPose = sensors(lastPossession).pose;

OutOfBounds
en:
% If a goal is scored, increment the score
if gameState.state == GameState.GoalScored
    ballPose = initBallPos;
    teamIdx = behavior(lastPossession).team;
    gameState.score(teamIdx) = gameState.score(teamIdx) + 1;
    % Else, place the ball back in bounds
else
    ballPose = placeBallInBounds();
end
setBallState(ballPose,0,robotPose(3));
